effect.shader:
vec2 u_xlat0;
vec4 u_xlat1;
vec2 u_xlat4;
void main()
{
    u_xlat0.x = dot(_rt_size.xy, _rt_size.xy);
    u_xlat0.x = inversesqrt(u_xlat0.x);
    u_xlat0.xy = u_xlat0.xx * _rt_size.xy;
    u_xlat4.xy = acScreenNorm.xy * vec2(1.07135487, 2.78672647);
    u_xlat0.xy = u_xlat0.xy * u_xlat4.xy;
    u_xlat1 = _rt_size.xyxy * vec4(0.239999995, 0.239999995, 0.0335999988, 0.0527999997);
    u_xlat0.xy = u_xlat0.xy * _rt_size.xy + u_xlat1.zw;
    u_xlat0.xy = u_xlat0.xy / u_xlat1.xy;
    u_xlat0.xy = clamp(u_xlat0.xy, 0.0, 1.0);
    fragColor = texture(inputImg, u_xlat0.xy);
    return;
}
